6	/** Browser-only: compress, cut out the background on-device, then compress the cutout. */
7	export async function processImage(
8	  file: File,
9	): Promise<{ original: Blob; cutout: Blob; cutoutMediaType: CutoutMediaType }> {
10	  const original = await imageCompression(file, compressionOptions());
11	  const raw = await removeBackground(original); // @imgly WASM, on-device
12	  // @imgly hands back an uncompressed PNG. It is the blob users actually see
13	  // (displayPath prefers the cutout), so it gets compressed too.
14	  const { blob: cutout, mediaType: cutoutMediaType } = await encodeCutout(raw);
15	  return { original, cutout, cutoutMediaType };
16	}
